package auth
import("crypto/rand";"encoding/base64";"encoding/json";"io";"net/http";"strings";"time")
type SignInRequest struct{Login string `json:"login"`;Password string `json:"password"`}
func SignInHandler(service *Service,w http.ResponseWriter,r *http.Request){if r==nil{return};if r.Method!=http.MethodPost{w.WriteHeader(http.StatusMethodNotAllowed);return};if service==nil{http.Error(w,"authentication unavailable",http.StatusServiceUnavailable);return};var req SignInRequest;dec:=json.NewDecoder(http.MaxBytesReader(w,r.Body,16<<10));if err:=dec.Decode(&req);err!=nil{http.Error(w,"invalid request",http.StatusBadRequest);return};var extra any;if err:=dec.Decode(&extra);err!=io.EOF{http.Error(w,"invalid request",http.StatusBadRequest);return};req.Login=strings.TrimSpace(req.Login);if req.Login==""||req.Password==""{http.Error(w,"login and password are required",http.StatusBadRequest);return};salt:=make([]byte,16);if _,err:=rand.Read(salt);err!=nil{http.Error(w,"authentication unavailable",http.StatusInternalServerError);return};result,err:=service.Authenticate(r.Context(),req.Login,[]byte(req.Password),salt);if err!=nil{http.Error(w,"invalid credentials",http.StatusUnauthorized);return};cookie:=&http.Cookie{Name:"ftn_session",Value:base64.RawURLEncoding.EncodeToString([]byte(result.Session.ID)),Path:"/",HttpOnly:true,Secure:true,SameSite:http.SameSiteLaxMode,Expires:time.Now().UTC().Add(24*time.Hour)};http.SetCookie(w,cookie);w.Header().Set("Content-Type","application/json");_ = json.NewEncoder(w).Encode(map[string]string{"identity_id":result.IdentityID})}
